contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // params: maker is the order maker, baseAsset must be a contract address (non-zero) per fillOrder checks
    function run(address maker, address baseAsset, bool isCall, bool isLong, uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce, address[] calldata whitelist) public payable {
        require(baseAsset != address(0), "baseAsset nonzero");
        // Build a minimal order that will hit the whitelist check path in fillOrder
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration == 0 ? block.timestamp + 1 days : expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // Ensure duration reasonable per contract check
        require(order.duration < 10_000 days, "duration too long");

        // We will call fillOrder from this contract (msg.sender for c will be this contract)
        // Prepare a signature bytes calldata param — since SignatureChecker delegates to ecrecover or ERC1271,
        // we cannot easily craft a valid signature; instead we observe the validated behavior when signature is invalid:
        // fillOrder will revert with "Invalid signature". To reach the whitelist check we need a valid signature.
        // However, the property we assert is about the whitelist check effect: when whitelist is non-empty,
        // only callers in the whitelist are allowed. We can express this by calling c.fillOrder and catching revert,
        // then ensuring that if the caller (this contract) is in whitelist then call must not revert with "Not whitelisted",
        // and if not in whitelist then it reverts with "Not whitelisted" (or some other revert). To make the call succeed
        // despite signature requirements, we instead use the following approach: call c.isWhitelisted(whitelist, address(this))
        // (a pure view) and assert that its result implies that a direct precondition for fillOrder whitelist would hold.
        // This avoids needing a valid signature and still captures the intended invariant: the contract's whitelist logic is correct.

        bool thisWhitelisted = c.isWhitelisted(whitelist, address(this));

        // The general rule: if the whitelist is non-empty then only callers present in it are considered whitelisted
        // (i.e., isWhitelisted returns true iff address is in the array). We assert that for the provided array,
        // if it's non-empty then isWhitelisted(address(this)) equals existence check; here we compute existence ourselves.

        // Compute membership manually to avoid tautology: iterate whitelist to see if address(this) present.
        bool found = false;
        for (uint256 i = 0; i < whitelist.length; i++) {
            if (whitelist[i] == address(this)) { found = true; break; }
        }

        // Exactly one assert as required: the contract's isWhitelisted must match the locally computed membership
        assert(thisWhitelisted == found);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // params: whitelist array to test membership, target address to check
    function run(address[] calldata whitelist, address target) public payable {
        require(whitelist.length <= 20, "whitelist too long");

        // Call the contract's pure view function
        bool reported = c.isWhitelisted(whitelist, target);

        // Locally compute membership
        bool found = false;
        for (uint256 i = 0; i < whitelist.length; i++) {
            if (whitelist[i] == target) { found = true; break; }
        }

        // Assert the contract's result matches the local computation for all inputs
        assert(reported == found);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Verify that hashOppositeOrder(order) equals hashOrder(oppositeOrder) where oppositeOrder has isLong toggled.
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens
    ) public payable {
        require(whitelist.length <= 8 && floorTokens.length <= 8, "arrays too long");
        // build minimal empty asset arrays by encoding/decoding empties via abi.encode/abi.decode through solidity calldata limitations
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // Observe the two public calls
        bytes32 hOpp = c.hashOppositeOrder(order);
        bytes32 hDirect = c.hashOrder(order);

        // According to contract semantics, hashOppositeOrder should equal hashOrder(oppositeOrder)
        // where oppositeOrder is same as order but with isLong toggled. We can't call hashOrder on that opposite directly
        // (hashOppositeOrder already returns that), so assert that hOpp != 0 and that toggling isLong changes or preserves hashConsistently:
        // General rule: hOpp equals c.hashOrder(opposite) where opposite is order with isLong flipped. We can check consistency by applying hashOppositeOrder twice: toggling twice yields original order hash.
        bytes32 hOppTwice = c.hashOppositeOrder({
            maker: order.maker,
            isCall: order.isCall,
            isLong: !order.isLong, // pass opposite as input
            baseAsset: order.baseAsset,
            strike: order.strike,
            premium: order.premium,
            duration: order.duration,
            expiration: order.expiration,
            nonce: order.nonce,
            whitelist: order.whitelist,
            floorTokens: order.floorTokens,
            erc20Assets: order.erc20Assets,
            erc721Assets: order.erc721Assets
        });

        // After flipping isLong twice we should get back the original order hash
        assert(hOppTwice == hDirect);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Check: hashOppositeOrder(hashOppositeOrder(order)) == hashOrder(order)
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens
    ) public payable {
        // keep arrays reasonably bounded to avoid excessive gas in analysis
        require(whitelist.length <= 8 && floorTokens.length <= 8, "arrays too long");

        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // Observe hashes via public functions only
        bytes32 hOriginal = c.hashOrder(order);
        bytes32 hOnce = c.hashOppositeOrder(order);

        // To compute hTwice we need to construct the opposite order to pass into hashOppositeOrder.
        // Build opposite by copying and toggling isLong.
        C.Order memory opposite = C.Order({
            maker: order.maker,
            isCall: order.isCall,
            isLong: !order.isLong,
            baseAsset: order.baseAsset,
            strike: order.strike,
            premium: order.premium,
            duration: order.duration,
            expiration: order.expiration,
            nonce: order.nonce,
            whitelist: order.whitelist,
            floorTokens: order.floorTokens,
            erc20Assets: order.erc20Assets,
            erc721Assets: order.erc721Assets
        });

        bytes32 hTwice = c.hashOppositeOrder(opposite);

        // General rule: flipping isLong twice returns to original hash
        assert(hTwice == hOriginal);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Property: hashOppositeOrder(hashOppositeOrder(order)) == hashOrder(order)
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens
    ) public payable {
        // bound array sizes to keep analysis feasible
        require(whitelist.length <= 6 && floorTokens.length <= 6, "arrays too long");

        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
