            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // one call to hashOppositeOrder
        bytes32 hOnce = c.hashOppositeOrder(order);

        // build the opposite order by toggling isLong (observe only via public types)
        C.Order memory opposite = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: !isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
