        });

        // apply hashOppositeOrder again on the opposite order
        bytes32 hTwice = c.hashOppositeOrder(opposite);

        // observe original hash via hashOrder
        bytes32 hOriginal = c.hashOrder(order);

        // Assert the general property: flipping isLong twice yields original order hash
        assert(hTwice == hOriginal);
    }

    receive() external payable {}
}
